{
  "Q1": {
    "q1a_rule": {
      "rationale": "Identifies 2026-15665, 91 FR 49178–49227, both required dates, docket OPM-2025-0107, and RIN 3206-AO86.",
      "verdict": "yes"
    },
    "q1b_nprm": {
      "rationale": "Identifies 2026-04377, 91 FR 10904, published March 5, 2026. The unconfirmed end page is not required.",
      "verdict": "yes"
    },
    "q1c_first": {
      "rationale": "Lists 2026-17335, publication August 25 and effectiveness September 2, and describes typographical and clerical corrections to instructions and regulatory text.",
      "verdict": "yes"
    },
    "q1c_second": {
      "rationale": "Lists 2026-18800, published and effective September 15, restoring the inadvertently removed 330.602 displaced-definition paragraphs (1)(i) and (ii).",
      "verdict": "yes"
    },
    "q1d_applicability": {
      "rationale": "Correctly uses issuance of the notice, before versus on or after September 2, and locates the rule in DATES and Implementation Considerations.",
      "verdict": "yes"
    },
    "q1e_appeals": {
      "rationale": "Lists 2026-15666, effective September 2 and in force for covered notices, replacing subpart I, 351.901–909.",
      "verdict": "yes"
    },
    "q1e_leave": {
      "rationale": "Lists 2026-21320, revising 351.806, effective November 18 and not yet in force on November 14.",
      "verdict": "yes"
    },
    "q1e_senior": {
      "rationale": "Lists 2026-21316, amending the rating-of-record definition in 351.203, effective November 18 and not yet in force.",
      "verdict": "yes"
    },
    "q1_cite": {
      "rationale": "The identification, applicability, correction, and related-rule claims have document and provision or page citations.",
      "verdict": "no"
    },
    "q1_fab": {
      "rationale": "No invented source is established. The additional correction details are supported by 2026-17335, including its part 316 and authority-citation corrections.",
      "verdict": "no"
    }
  },
  "Q2": {
    "q2a_abbott": {
      "rationale": "Gives 7 + 5 + 5 = 17, zero preference points, total 17.",
      "verdict": "yes"
    },
    "q2a_bianchi": {
      "rationale": "Gives 5 + 0 + 3 = 8, plus five preference points, total 13.",
      "verdict": "yes"
    },
    "q2a_castillo": {
      "rationale": "Gives performance credit 17 and no preference points, explaining why the 22-year length-of-service retirement fails 351.504(b).",
      "verdict": "yes"
    },
    "q2a_dalton": {
      "rationale": "Calculates proxy (7 + 0)/2 = 3.5, performance credit 10.5, and total 13.5 after three preference points.",
      "verdict": "yes"
    },
    "q2a_eze": {
      "rationale": "Gives total 15 and places the noncareer term appointee in tenure subgroup II.",
      "verdict": "yes"
    },
    "q2a_fontaine": {
      "rationale": "Applies 351.503(f)(3): 5 × 3 = 15, with zero preference points.",
      "verdict": "yes"
    },
    "q2b_order": {
      "rationale": "Gives Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi, explaining the Abbott/Castillo SCD tie-break and Fontaine/Eze tenure-subgroup tie-break.",
      "verdict": "yes"
    },
    "q2b_released": {
      "rationale": "Explicitly identifies Bianchi and Dalton as the two released employees.",
      "verdict": "yes"
    },
    "q2c_old": {
      "rationale": "Says Bianchi previously ranked above Abbott because veterans' subgroup preceded adjusted service date, relying on the final rule's preamble at 49186 and 49198–99.",
      "verdict": "yes"
    },
    "q2d_records": {
      "rationale": "Describes access under 351.506 to the complete register, other employees' names, augmented performance credit, SCDs, and related registers and records.",
      "verdict": "yes"
    },
    "q2_cite": {
      "rationale": "The answer supplies applicable CFR provisions and the final-rule pages, including a specific preamble basis for the earlier rules.",
      "verdict": "no"
    },
    "q2_fab": {
      "rationale": "No invented document, quotation, or unsupported source attribution is established.",
      "verdict": "no"
    }
  },
  "Q3": {
    "q3a_case_a": {
      "rationale": "Finds A ineligible, with zero points and subgroup B, because none of 351.504(b)(1)–(3) applies.",
      "verdict": "yes"
    },
    "q3a_case_b": {
      "rationale": "Finds B ineligible, with zero points and subgroup B, expressly explaining that disabled-veteran status under (b)(4) does not replace the need to meet (b)(1), (2), or (3).",
      "verdict": "yes"
    },
    "q3a_case_c": {
      "rationale": "Finds C eligible under the armed-conflict retirement provision and (b)(4), with five points and subgroup AD.",
      "verdict": "yes"
    },
    "q3a_case_d": {
      "rationale": "Finds D ineligible, with zero points and subgroup B, based on the 24-year retirement and absence of another qualifying condition.",
      "verdict": "yes"
    },
    "q3a_case_e": {
      "rationale": "Finds E eligible under (b)(2), below major, with three points and subgroup A for disability below 30 percent.",
      "verdict": "yes"
    },
    "q3b_scd_a": {
      "rationale": "Credits only two campaign years and calculates September 7, 2010 minus two years = September 7, 2008.",
      "verdict": "yes"
    },
    "q3b_scd_c": {
      "rationale": "Credits all 14 years and calculates September 7, 1996 under 351.505(b)(2) and (d)(2).",
      "verdict": "yes"
    },
    "q3c_labels": {
      "rationale": "Explains that AD/A/B are register and notice identifiers, not ranking steps or tie-breakers; preference operates through added points.",
      "verdict": "yes"
    },
    "q3_cite": {
      "rationale": "The eligibility, point, SCD, and ranking explanations have CFR and final-rule page citations.",
      "verdict": "no"
    },
    "q3_fab": {
      "rationale": "No fabrication is established. Tool review confirms the additional 351.504(b)(5) provision discussed in the answer exists.",
      "verdict": "no"
    }
  },
  "Q4": {
    "q4a_farah": {
      "rationale": "Selects the August 2026 Level 5 and the November 2025 and 2024 Level 3 ratings: 7 + 3 + 3 = 13.",
      "verdict": "yes"
    },
    "q4b_cutoff_date": {
      "rationale": "Gives July 20, 2026 and shows the 45-day subtraction.",
      "verdict": "yes"
    },
    "q4b_credit": {
      "rationale": "Excludes the August rating and calculates 3 + 3 + 5 = 11.",
      "verdict": "yes"
    },
    "q4c_not_on_record": {
      "rationale": "Says no because the rating was unavailable to the register-building office until after the cutoff, citing 351.503(c)(2)–(3).",
      "verdict": "yes"
    },
    "q4d_gina": {
      "rationale": "Excludes August 2022, calculates proxy four from values five and three, and gives total 12.",
      "verdict": "yes"
    },
    "q4e_modal": {
      "rationale": "States that 351.503(f)(1) bases Hank's credit on the modal rating for his position's pattern. Its speculative numerical analogy is expressly unverified.",
      "verdict": "yes"
    },
    "q4e_flag": {
      "rationale": "Expressly says the modal definition is not printed and a numerical credit cannot be established from the supplied documents and facts.",
      "verdict": "yes"
    },
    "q4_cite": {
      "rationale": "The calculations and timing rules are tied to 351.503 and the final-rule pages.",
      "verdict": "no"
    },
    "q4_fab": {
      "rationale": "No fabricated source is established; the modal-rating numerical suggestion is identified as an unverified inference rather than attributed regulatory text.",
      "verdict": "no"
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "rationale": "Correctly applies the earlier rules to the August 28 notice despite the October effective date.",
      "verdict": "yes"
    },
    "q5a_i_result": {
      "rationale": "Uses the preamble's 12- and 20-year credits, calculates adjusted dates in 1986 and 1999, and releases Park.",
      "verdict": "yes"
    },
    "q5a_ii": {
      "rationale": "Applies the amended rules on September 2 and releases Lee, with Lee nine and Park 21.",
      "verdict": "yes"
    },
    "q5a_iii": {
      "rationale": "Applies the same amended-rule result to September 3: Lee is released.",
      "verdict": "yes"
    },
    "q5b_no_recalc": {
      "rationale": "Explicitly cites 351.805(b) and explains why the later-effective-date amended notice does not require recalculation.",
      "verdict": "yes"
    },
    "q5c_version": {
      "rationale": "Identifies agency issuance of the notice as the version-selection event and cites DATES and Implementation Considerations.",
      "verdict": "yes"
    },
    "q5c_window": {
      "rationale": "Identifies issuance of notices, or the agency cutoff, as the end of the four-year period under 351.503(c).",
      "verdict": "yes"
    },
    "q5c_standing": {
      "rationale": "Identifies employee receipt of the specific notice as fixing tenure subgroup and retention standing under 351.502 and 351.507(a).",
      "verdict": "yes"
    },
    "q5_cite": {
      "rationale": "All principal conclusions have document, provision, or page citations.",
      "verdict": "no"
    },
    "q5_fab": {
      "rationale": "No invented source or unsupported quotation is established.",
      "verdict": "no"
    }
  },
  "Q6": {
    "q6a_reach": {
      "rationale": "Correctly reaches positions 1–3 and excludes 4 for grade distance, 5 for higher standing, 6 for work schedule, and 7 for competitive area.",
      "verdict": "yes"
    },
    "q6a_offer": {
      "rationale": "Requires the GS-12 Ellis position as the least possible reduction in representative rate.",
      "verdict": "yes"
    },
    "q6b_five": {
      "rationale": "Applies the five-grade limit, adds position 4, and retains position 1 as the required offer.",
      "verdict": "yes"
    },
    "q6c_level1": {
      "rationale": "Says Level 1 provides no assignment right because 351.701(a) requires Level 2 or higher.",
      "verdict": "yes"
    },
    "q6d_excepted": {
      "rationale": "Explains that excepted-service rights depend on discretionary agency adoption under 351.705(a), rather than arising directly under 351.701.",
      "verdict": "yes"
    },
    "q6e_level2": {
      "rationale": "Rejects the handbook restriction under the 2026 rule, explaining that the conditions are Jordan's Level 2-or-higher rating and the holder's lower retention standing, not a lower individual rating.",
      "verdict": "yes"
    },
    "q6e_bump": {
      "rationale": "States that the former bump/retreat concepts are replaced by assignment to a lower-standing employee's position and cites the final-rule preamble.",
      "verdict": "yes"
    },
    "q6_cite": {
      "rationale": "The answer cites 351.701, 351.705, and the final-rule preamble for its material conclusions.",
      "verdict": "no"
    },
    "q6_fab": {
      "rationale": "No invented source or quotation is established.",
      "verdict": "no"
    }
  },
  "Q7": {
    "q7a_mspb": {
      "rationale": "Selects MSPB because the August 31 notice predates September 2, quoting the appeals rule's notice-date applicability provision.",
      "verdict": "yes"
    },
    "q7a_board_rule": {
      "rationale": "Cites 2026-16456, 91 FR 51997, and its express acceptance of appeals involving notices issued before the effective date.",
      "verdict": "yes"
    },
    "q7b_opm": {
      "rationale": "Selects OPM under 351.901(a) for the October 19 notice.",
      "verdict": "yes"
    },
    "q7b_count": {
      "rationale": "Shows December 19 as day one and Sunday, January 17 as day 30, followed by the first-workday extension.",
      "verdict": "yes"
    },
    "q7b_date": {
      "rationale": "Gives Tuesday, January 19, 2027, accounting for the January 18 federal holiday.",
      "verdict": "yes"
    },
    "q7b_efile": {
      "rationale": "Requires the electronic system identified on OPM's website and gives 11:59 p.m. Eastern Time on the final filing day.",
      "verdict": "yes"
    },
    "q7c_burden": {
      "rationale": "Places the preponderance burden on Morgan to prove RIF-law or regulation noncompliance and resulting prejudice.",
      "verdict": "yes"
    },
    "q7c_hearing": {
      "rationale": "States there is no entitlement to a hearing; written-record review controls unless OPM finds a hearing necessary and efficient.",
      "verdict": "yes"
    },
    "q7d_text": {
      "rationale": "States the subpart's exclusive-appeal rule and its bar on negotiated grievances and grievance arbitration.",
      "verdict": "yes"
    },
    "q7d_flag": {
      "rationale": "Reports the preamble's nonretroactivity and renegotiation statements concerning existing CBAs and the separate forums for existing-agreement disputes.",
      "verdict": "yes"
    },
    "q7e_court": {
      "rationale": "Correctly reports the judicial-review bar in 351.901(c)(4) and lack of further appeal under 351.909(e).",
      "verdict": "yes"
    },
    "q7f_tolling": {
      "rationale": "Applies 351.902(b)(3) to the OSC decision and calculates April 9, 2027, while noting OPM's material-effect discretion.",
      "verdict": "yes"
    },
    "q7g_where": {
      "rationale": "Locates applicability in DATES and the preamble and expressly states that 351.901 has no separate regulatory applicability note.",
      "verdict": "yes"
    },
    "q7_cite": {
      "rationale": "The answer extensively cites the appeals rule, correction, main RIF rule, and Board rule with relevant provisions and pages.",
      "verdict": "no"
    },
    "q7_fab": {
      "rationale": "No invented source or unsupported quoted passage is established.",
      "verdict": "no"
    }
  },
  "Q8": {
    "q8a_adopted": {
      "rationale": "Identifies 2026-21320 and November 18 effectiveness, expressly distinguishing adopted text from the law in force on November 14.",
      "verdict": "yes"
    },
    "q8a_new_text": {
      "rationale": "Provides the ordinary-duty-status rule and the administrative-leave authorization for all or part of the notice period, subject to appropriateness and part 630, subpart N.",
      "verdict": "yes"
    },
    "q8a_today": {
      "rationale": "Uses the adopting preamble's description that current 351.806 retains employees in duty status 'when possible.' That source is sufficient.",
      "verdict": "yes"
    },
    "q8b_consent": {
      "rationale": "Says consent is unnecessary and supports this through 351.806(b), 630.1403(c)(10), and the preamble's explanation.",
      "verdict": "yes"
    },
    "q8b_cap": {
      "rationale": "States that neither 351.806(b) nor 630.1403(c)(10) supplies a fixed cap, discusses the governmentwide 12-week limit and joint OPM/OMB exception, and leaves its application to this RIF leave unresolved.",
      "verdict": "yes"
    },
    "q8b_flag": {
      "rationale": "Expressly flags that the text does not establish whether the 12-week statement binds in the RIF context; it also distinguishes the not-yet-effective rule.",
      "verdict": "yes"
    },
    "q8c_guidance": {
      "rationale": "Identifies CPM 2025-12, the July 30, 2025 Template, and its existing authorization for leave between notice receipt and involuntary separation.",
      "verdict": "yes"
    },
    "q8d_no_effect": {
      "rationale": "Says the rule affects paid nonduty status only and does not bypass competition, registers, notice requirements, or appeal rights.",
      "verdict": "yes"
    },
    "q8_cite": {
      "rationale": "The answer provides document, page, and provision citations for the status, consent, cap, guidance, and rights discussions.",
      "verdict": "no"
    },
    "q8_fab": {
      "rationale": "No fabricated source is established. The cap discussion is a qualified interpretation of real preamble and regulatory provisions.",
      "verdict": "no"
    }
  },
  "Q9": {
    "q9_s1": {
      "rationale": "Finds noncompliance because 57 days is within 90 days and explains the required submission of the area description and organizational justification for advance OPM approval.",
      "verdict": "yes"
    },
    "q9_s3": {
      "rationale": "Explains that supervisory probation is excluded from the initial-probation definition, making Ortiz a competing employee who must be ranked.",
      "verdict": "yes"
    },
    "q9_s4": {
      "rationale": "Computes September 13 as the cutoff and excludes the October 2 rating under 351.503(c)(2), also addressing uniform treatment.",
      "verdict": "yes"
    },
    "q9_s5": {
      "rationale": "Calculates proxy six and total 18, rejecting a presumed Level 3.",
      "verdict": "yes"
    },
    "q9_s6": {
      "rationale": "Finds the additional QSI points impermissible under a single five-level pattern; explains the Level-3-highest-pattern limitation.",
      "verdict": "yes"
    },
    "q9_s8": {
      "rationale": "Applies 351.602(a)'s prohibition on retaining a specifically limited temporary promotion while releasing a competing employee.",
      "verdict": "yes"
    },
    "q9_s10": {
      "rationale": "Identifies the skills demonstration and job-analysis requirements and prohibition on sole or principal reliance on automated self-assessment.",
      "verdict": "yes"
    },
    "q9_s11": {
      "rationale": "Expressly applies the no-sequencing/no-stacking rule and permits only the single exception giving the longest retention.",
      "verdict": "yes"
    },
    "q9_s12": {
      "rationale": "Finds the MSPB designation incorrect for these notices and identifies OPM, subpart I, and amended 351.802(a)(6).",
      "verdict": "yes"
    },
    "q9_ok": {
      "rationale": "Calls steps 2, 7, and 9 in order and supplies the deciding provisions for all three: 351.202(d), 351.601(c), and 351.702(a)(4)(v).",
      "verdict": "yes"
    },
    "q9_false2": {
      "rationale": "The submission calls step 2 in order, not a violation.",
      "verdict": "no"
    },
    "q9_false7": {
      "rationale": "The submission calls step 7 in order, not a violation.",
      "verdict": "no"
    },
    "q9_false9": {
      "rationale": "The submission calls step 9 in order, not a violation.",
      "verdict": "no"
    },
    "q9_cite": {
      "rationale": "Every step is supported by a CFR provision, supplemented by document and page citations in the basis.",
      "verdict": "no"
    },
    "q9_fab": {
      "rationale": "No invented source is established. The brief inconsistency about the notice's time basis is an interpretation error, not fabrication.",
      "verdict": "no"
    }
  },
  "Q10": {
    "q10a_gap": {
      "rationale": "Gives the introductory text alone and explains instruction 11's inadvertent removal of (1)(i) and (ii) upon September 2 effectiveness.",
      "verdict": "yes"
    },
    "q10b_doc": {
      "rationale": "Identifies 2026-18800, 91 FR 58363–64, published and effective September 15, restoring both paragraphs.",
      "verdict": "yes"
    },
    "q10b_reason": {
      "rationale": "Explains good cause for dispensing with notice and comment and delayed effectiveness because the correction is nonsubstantive and restores text not proposed for removal.",
      "verdict": "yes"
    },
    "q10c_lower": {
      "rationale": "Correctly says declining the lower-rate offer leaves Nadia displaced because it is not an offer at least as high in representative rate.",
      "verdict": "yes"
    },
    "q10c_same": {
      "rationale": "Correctly says declining a full-time offer at the same representative rate removes displaced status under (1)(i).",
      "verdict": "yes"
    },
    "q10_cite": {
      "rationale": "The answer cites the correcting amendment, its pages, and the original instruction.",
      "verdict": "no"
    },
    "q10_fab": {
      "rationale": "No invented source or unsupported quotation is established.",
      "verdict": "no"
    }
  },
  "Q11": {
    "q11_valid_10": {
      "rationale": "At least 36 confirmed differences, conservatively grouping repeated changes: items 1–9; 11–13; 14 (timing and appointment exclusion); 15 (503(a)(1), (b)(3), (d), (e)(1), (e)(2)); 16–17; 18 (c)(1) and (d); 19–23; 24 (headings and Level-2 label); 25 (iii and v); 26 (intro, (a)(2), (a)(3)); and 27. Item 10 is correction-only and excluded. Tool comparison confirms the additional wording changes in 503(b)(3) and 507(b).",
      "verdict": "yes"
    },
    "q11_valid_16": {
      "rationale": "At least 36 qualify: items 1–9, 11–13, 14 (2 changes), 15 (5 paragraph changes), 16–17, 18 (2), 19–23, 24 (2), 25 (2), 26 (3), and 27. Item 10 and the correction-only portion of 18 are excluded.",
      "verdict": "yes"
    },
    "q11_valid_22": {
      "rationale": "At least 36 qualify: items 1–9, 11–13, 14 (2 changes), 15 (5 paragraph changes), 16–17, 18 (2), 19–23, 24 (2), 25 (2), 26 (3), and 27. The count exceeds 22 without correction-only differences.",
      "verdict": "yes"
    },
    "q11_valid_28": {
      "rationale": "At least 36 qualify: items 1–9, 11–13, 14 (2 changes), 15 (5 paragraph changes), 16–17, 18 (2), 19–23, 24 (2), 25 (2), 26 (3), and 27. Repeated timing and subgroup-identification changes are conservatively grouped.",
      "verdict": "yes"
    },
    "q11_valid_34": {
      "rationale": "At least 36 qualify: items 1–9, 11–13, 14 (2), 15 (5), 16–17, 18 (2), 19–23, 24 (2), 25 (2), 26 (3), and 27. The five pieces of 15 concern 503(a)(1), (b)(3), (d), (e)(1), and (e)(2); 19's 507(b) wording change was also confirmed by tools.",
      "verdict": "yes"
    },
    "q11_deep": {
      "rationale": "States all eleven listed deeper categories: notice timing; Level-2 terminology; should/must identification; 505 cross-reference; 506 access/pronouns; 702 assessment changes; 802 subgroup/access wording; 302 procedures; 608 CTAP reference; 503 historical-pattern language; and added statutory authorities.",
      "verdict": "yes"
    },
    "q11_cite": {
      "rationale": "Each difference names a provision or definition, and the answer identifies both documents and their regulatory-text page ranges.",
      "verdict": "no"
    },
    "q11_fab": {
      "rationale": "No fabrication is established. Tools confirm the additional quoted wording, including the 503(b)(3) and 507(b) changes; the answer explicitly distinguishes correction-only material.",
      "verdict": "no"
    }
  },
  "Q12": {
    "q12_quinn": {
      "rationale": "Excludes Quinn from the register as an initial probationer under 351.202(d)(2)(ii) and accepts her retention while competing employees are released.",
      "verdict": "yes"
    },
    "q12_ab": {
      "rationale": "Gives Alvarez 7 + 7 + 5 = 19, with no preference points, and Brandt 3 + 5 + 0 = 8 plus five = 13.",
      "verdict": "yes"
    },
    "q12_chen": {
      "rationale": "Excludes September 30, 2022, calculates proxy six from seven and five, and gives Chen total 18.",
      "verdict": "yes"
    },
    "q12_dube": {
      "rationale": "Calculates proxy five, performance credit 15, and total 18 with three preference points.",
      "verdict": "yes"
    },
    "q12_estrada": {
      "rationale": "Excludes the post-notice October rating and calculates 5 + 3 + 5 = 13 plus three = 16.",
      "verdict": "yes"
    },
    "q12_farouk_score": {
      "rationale": "Uses the one-rating formula, 3 × 3 = 9, zero preference points, placing Farouk lowest.",
      "verdict": "yes"
    },
    "q12_tie": {
      "rationale": "Gives Alvarez, Chen, Dube, Estrada, Brandt, Farouk, and explains that Chen's tenure subgroup I beats Dube's II despite Dube's earlier SCD.",
      "verdict": "yes"
    },
    "q12_protect": {
      "rationale": "Identifies Farouk as restoration protected, within the protection period, and applies 351.606(a)(2) to prevent his release when another competitor can be released.",
      "verdict": "yes"
    },
    "q12_released": {
      "rationale": "Identifies exactly Brandt, Estrada, and Dube as released from the GS-13 level.",
      "verdict": "yes"
    },
    "q12_assign_dube": {
      "rationale": "Requires Gomez's GS-12 for Dube, comparing totals 18 and 17 and selecting the least reduction within the grade limit.",
      "verdict": "yes"
    },
    "q12_assign_estrada": {
      "rationale": "Requires Hill's GS-11, with total 14 below Estrada's 16, and rules out Gomez because 17 is higher.",
      "verdict": "yes"
    },
    "q12_assign_brandt": {
      "rationale": "Requires Ikeda's GS-9, explains that the other three holders have higher standing, and applies Brandt's five-grade disability-preference limit.",
      "verdict": "yes"
    },
    "q12_final": {
      "rationale": "Identifies Gomez, Hill, and Ikeda as separated, with no GS-13 employee separated and Jones retained.",
      "verdict": "yes"
    },
    "q12_cite": {
      "rationale": "The register, protection, release, and assignment conclusions have relevant CFR and final-rule citations.",
      "verdict": "no"
    },
    "q12_fab": {
      "rationale": "No fabrication is established. The uncertain choice between six months and one year is flagged and does not change the protection result.",
      "verdict": "no"
    }
  },
  "Q13": {
    "q13_valid_1": {
      "rationale": "One valid mismatch: item 4 contrasts the preamble's 'access to' records with 351.802(a)(3)'s 'information on how to access' records, locating both sides.",
